// idiomatic: the GA, the one method AGENTS.md presents for binary genomes ("Choosing the
// pieces"), with the defaults (crossover rate 0.9, mutation rate 1, generational with an
// elitism of 1), `UniformCrossover`, the first crossover the table lists for binary genomes,
// and the literature's population 100, binary tournament and bit-flip at 1 / n
let build = |seed| {
    Ga::builder(Binary::new(size)?)
        .population_size(GA_POPULATION)
        .select(Tournament::new(TOURNAMENT)?)
        .crossover(UniformCrossover::new())
        .mutate(BitFlip::per_gene(1.0 / size as f64)?)
        .seed(seed)
        .build()
};

|budget| {
    let genotype = BinaryGenotype::builder()
        .with_genes_size(args.size)
        .build()
        .unwrap();
    // idiomatic: AGENTS.md "If unsure, start here", for binary genotypes:
    // SelectTournament(0.5, 0.02, 4), CrossoverUniform(0.7, 0.8), MutateSingleGene(0.2);
    // population 100 as in README.md "Quick Usage", which is this problem (100 genes,
    // count the true values, target 100). The only ending condition is the target
    // (with_max_stale_generations isn't set), so a run ends at the target or through the
    // abort flag, which a stall also sets (then the attempt restarts).
    restarts(seed, |run_seed| {
        let evolve = Evolve::builder()
            .with_genotype(genotype.clone())
            .with_fitness(OneMax(budget.clone()))
            .with_target_fitness_score(target as FitnessValue)
            .with_abort_flag(budget.abort_flag.clone())
            .with_rng_seed_from_u64(run_seed)
            .with_target_population_size(100)
            .with_select(SelectTournament::new(0.5, 0.02, 4))
            .with_crossover(CrossoverUniform::new(0.7, 0.8))
            .with_mutate(MutateSingleGene::new(0.2))
            .with_reporter(Generations::new(budget))
            .call()
            .unwrap();
        let score = evolve.best_fitness_score();
        let conclusive = score == Some(target as FitnessValue)
            || (budget.aborted() && !budget.resume_after_stall());
        // maximized: restarts keeps the smallest
        (
            evolve.best_genes(),
            score.map(|score| -score),
            conclusive,
            evolve.state.current_generation,
        )
    })
},

def onemax_solvers(size, mode):
    def problem(counter):
        return SingleProblem(counter, onemax, size, 0, 1, vtype=bool)

    if mode == "matched":
        # not run: the matched GA is generational without elitism, and pymoo's GA always keeps the
        # best of its parents and children (FitnessSurvival); pymoo has no generational survival
        return []

    # docs/source/customization/binary.md: GA for binary variables (the knapsack example). Its
    # termination, ("n_gen", 100), is only a budget: the GA runs to the budget
    def algorithm():
        return GA(
            pop_size=200,
            sampling=BinaryRandomSampling(),
            crossover=TwoPointCrossover(),
            mutation=BitflipMutation(),
            eliminate_duplicates=True,
        )
    return [("ga", problem, algorithm, restart_seed, no_convergence)]

// radiate's binary example, the knapsack (examples/rust/knapsack, lines 11-18): a
// SubSetCodec, whose genome is a BitChromosome with one bit per item (here the items are
// the gene indices, and the fitness counts the bits), max_age 50, and the other engine
// defaults (population 100, roulette offspring selection, tournament of 3 for the
// survivors, offspring fraction 0.8)
let build = |budget: Arc<Budget>| {
    let builder = GeneticEngine::builder()
        .codec(SubSetCodec::new((0..size).collect::<Vec<usize>>()))
        .raw_fitness_fn(fitness(budget))
        .max_age(50);
    match solver {
        // the example as it is, with the default alterers UniformCrossover(0.5) and
        // UniformMutator(0.1), which redraws each bit with probability 0.1 (flips it with
        // 0.05)
        "ga" => builder.build(),
        // the binary recipe with Uniform crossover, at the example's 0.5
        "ga_uniform" => builder
            .alter(alters!(UniformCrossover::new(0.5), UniformMutator::new(0.01)))
            .build(),
        // the binary recipe with Multi-point crossover, 2 points, at the example's 0.5
        _ => builder
            .alter(alters!(MultiPointCrossover::new(0.5, 2), UniformMutator::new(0.01)))
            .build(),
    }
};

