// "Hello World (Ones counting)", the first example of jenetics.io and of the
// README (BitChromosome.of(n, 0.5)), also the delivered program
// jenetics.example/OnesCounting.java: the engine defaults, population 50,
// TournamentSelector(3) for offspring and survivors, SinglePointCrossover(0.2),
// Mutator(0.15), 60% offspring, maximal age 70. Both end the stream with a
// generation limit only (limit(100), limit(10)), which the budget replaces.
// (The manual's listing, section 6.1, sets other values; see the page.)
solvers.add(new Solver("ga", (budget, seed) -> evolve(
    Engine.builder((Genotype<BitGene> gt) -> countOnes(gt, budget),
            Genotype.of(BitChromosome.of(size, 0.5)))
        .executor(Runnable::run)
        .build(),
    budget, seed)));

static <G extends Gene<?, G>, C extends Comparable<? super C>> long evolve(
        Engine<G, C> engine, Budget budget, int steadyGenerations, long seed) {
    long generations = 0;
    for (int restart = 0; ; restart++) {
        if (restart > 0) seed((seed + 1) * 1_000_000 + restart);
        long[] attempt = {0};
        int[] idle = {0};
        // every generation's end, the first of each attempt (its initial population and its
        // first offspring) included: this limit comes first, so it sees every result, also
        // the one that the steady-fitness limit ends the attempt at
        var stream = engine.stream().limit(result -> {
            idle[0] = budget.evaluations == budget.generationEnd ? idle[0] + 1 : 0;
            budget.endGeneration();
            return true;
        });
        if (steadyGenerations > 0) stream = stream.limit(Limits.bySteadyFitness(steadyGenerations));
        stream
            .limit(result -> {
                attempt[0] = result.generation();
                return !budget.done() && idle[0] < STALL_GENERATIONS;
            })
            .forEach(result -> {});
        generations += attempt[0];
        if (budget.done()) return generations;
    }
}

// jmetal-algorithm examples/singleobjective/ElitistEvolutionStrategyRunner.java
// (on OneMax): the elitist (μ + λ) evolution strategy with μ 1, λ 10,
// BitFlipMutation(1 / bits)
solvers.add(new Solver("es", (budget, seed) -> {
    var es = new EvolutionStrategyBuilder<BinarySolution>(new OneMaxProblem(size, budget),
            new BitFlipMutation<>(1.0 / size), EvolutionStrategyBuilder.EvolutionStrategyVariant.ELITIST)
        .setMaxEvaluations(Integer.MAX_VALUE)
        .setMu(1)
        .setLambda(10)
        .build();
    runClassic(es::run);
    // μ = 1 initial solution, then λ = 10 a generation
    budget.fixedGenerations(1, 10);
    return Math.max(0, budget.evaluations - 1) / 10;
}));

// jmetal-component examples/singleobjective/geneticalgorithm/
// GenerationalGeneticAlgorithmBinaryExample.java (on OneMax): population 100,
// 100 children, binary tournament, SinglePointCrossover(0.9),
// BitFlipMutation(1 / bits), (μ + λ) replacement (GeneticAlgorithmBuilder's)
solvers.add(new Solver("ga", (budget, seed) -> runComponent(budget, termination ->
    new GeneticAlgorithmBuilder<>("GGA", new OneMaxProblem(size, budget), 100, 100,
            new SinglePointCrossover<>(0.9), new BitFlipMutation<>(1.0 / size))
        .setTermination(termination)
        .build())));

static <S extends Solution<?>> long runComponent(Budget budget,
                                                 Function<Termination, EvolutionaryAlgorithm<S>> build) {
    long[] generations = {0};
    EvolutionaryAlgorithm<S> algorithm = build.apply(status -> {
        budget.endGeneration();
        generations[0]++;
        return false;
    });
    try {
        algorithm.run();
    } catch (Stop stop) {
        // the target, the budget or the time cap
    }
    return generations[0];
}

void solve_onemax(const Args &args, long long seed) {
    // matched OneMax isn't run: openGA has no two-point crossover or bit flip of its own (see the
    // top of the file). Print nothing.
    if (args.mode == "matched") return;
    const int size = args.size;
    const std::function<void(BitsGA &)> setup = [size](BitsGA &ga) {
        configure(ga);
        // random 0/1 genes, as the examples' init_genes draws each gene uniformly in its range
        // (examples/so-rastrigin/so-rastrigin.cpp L36-40)
        ga.init_genes = [size](Bits &b, const Rnd01 &rnd01) {
            b.x.resize(size);
            for (auto &v : b.x) v = rnd01() < 0.5 ? 1 : 0;
        };
        ga.eval_solution = [](const Bits &b, Cost &c) {
            c.cost = -onemax(b.x);  // openGA minimizes
            budget.record(c.cost);
            return true;
        };
        ga.calculate_SO_total_fitness = [](const BitsGA::thisChromosomeType &X) { return X.middle_costs.cost; };
        ga.SO_report_generation = [](int, const EA::GenerationType<Bits, Cost> &, const Bits &) {};
        // bit flip with probability 1 / size per gene: openGA has no binary operators, and the
        // generated real-valued mutation (assist/main.js L259-279) doesn't apply to 0/1 genes
        // (openGA.pdf p. 6: "the clients should edit these operators according to their need")
        ga.mutate = [size](const Bits &base, const Rnd01 &rnd01, double) {
            Bits child = base;
            for (auto &v : child.x)
                if (rnd01() < 1.0 / size) v ^= 1;
            return child;
        };
        // openGA assist's generated settings (assist/main.js): population "medium" 200
        // (L435-436, the default selection, assist/index.html L24), crossover_fraction 0.7 and
        // mutation_rate 0.2 (L460-461), elite_count 10 (L465), best_stall_max 10 (L464) with the
        // other stall settings at openGA's defaults. Its generation_max 1000 (L447) is lifted.
        // With 0/1 genes, the generated crossover, a random mix of the parents per gene
        // (L282-295), becomes uniform crossover.
        ga.population = 200;
        ga.crossover_fraction = 0.7;
        ga.mutation_rate = 0.2;
        ga.elite_count = 10;
        assist_stall(ga);
        ga.crossover = [](const Bits &a, const Bits &b, const Rnd01 &rnd01) {
            Bits child = a;
            for (size_t i = 0; i < child.x.size(); i++)
                if (rnd01() < 0.5) child.x[i] = b.x[i];
            return child;
        };
    };

    const RunResult run = run_ga<BitsGA>(seed, args.max_evaluations, args.max_seconds, -double(size), setup);
    const std::vector<std::uint8_t> bits(run.best_genes.begin(), run.best_genes.end());
    const double best = onemax(bits);
    print_single(args, "ga", seed, run, best, size, best >= size, true);
}

RunResult run_ga(long long seed, long long max_evaluations, double max_seconds, double target,
                 const std::function<void(GA &)> &setup) {
    start_budget(max_evaluations, max_seconds, target);
    RunResult result{0.0, 0, 0, 0};
    for (long long attempt = 0;; attempt++) {
        GA ga;
        setup(ga);
        seed_ga(ga, attempt_seed(std::uint64_t(seed), std::uint64_t(attempt)));
        long long before = budget.evaluations;
        ga.solve_init();
        result.last_generation = budget.evaluations - before;
        bool converged = false;
        while (!converged && !budget.reached() && !budget.exhausted()) {
            before = budget.evaluations;
            converged = ga.solve_next_generation() != EA::StopReason::Undefined;
            result.last_generation = budget.evaluations - before;
            result.generations++;
        }
        const auto &generation = ga.last_generation;
        const auto &best = generation.chromosomes[generation.best_chromosome_index];
        if (best.total_cost < result.best_cost) {
            result.best_cost = best.total_cost;
            result.best_genes = numbers(best.genes);
        }
        if (budget.reached() || budget.exhausted()) break;
        result.restarts++;
    }
    result.seconds = std::chrono::duration<double>(Clock::now() - budget.start).count();
    return result;
}
